"use client";
import { useEffect, useState } from "react";
import type { Order } from "../../../lib/orders";
import type { SiteContent } from "../../../lib/site-types";
export default function OrdersPage(){const [orders,setOrders]=useState<Order[]>([]),[content,setContent]=useState<SiteContent|null>(null);useEffect(()=>{fetch("/api/orders").then(r=>r.ok?r.json():[]).then(setOrders);fetch("/api/content").then(r=>r.json()).then(setContent);},[]);const phone=content?.whatsapp||"";return <main className="admin"><div className="adminHead"><div><small>پنل مدیریت</small><h1>پیگیری سفارش‌ها</h1></div><div><a href="/admin">بازگشت به پنل</a></div></div><section className="orderList"><h2>سفارش‌های ثبت‌شده ({orders.length})</h2>{orders.length?orders.map(o=>{const text=`سلام ${o.parentName} عزیز، درخواست شما برای ${o.packageName} دریافت شد. برای هماهنگی و ارسال لینک پرداخت با شما در تماس هستیم.\nنام کودک: ${o.childName}\nسن: ${o.childAge}`;return <article key={o.id}><div><b>{o.parentName}</b><span>{o.phone} · {o.packageName}</span><small>کودک: {o.childName} | {o.childAge}</small></div><a className="button" target="_blank" href={`https://wa.me/${o.phone.replace(/\D/g,"").replace(/^0/,"98")}?text=${encodeURIComponent(text)}`}>ارسال واتساپ به مشتری</a></article>}):<p>هنوز سفارشی ثبت نشده است.</p>}</section><p className="adminHint">برای اعلان کاملاً خودکار در لحظهٔ ثبت سفارش، در مرحلهٔ انتشار سایت API واتساپ بیزینس را متصل می‌کنیم.</p></main>}
